use vstd::prelude::*;

verus! {

/// Copy a vector of i8 by iterating and pushing each element.
/// Ensures the result has the same length and contents as the input.
fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
    ensures result.len() == arr.len()
    ensures forall |j: usize| j < arr.len() ==> result[j] == arr[j]
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    // Loop over each index, copying arr[i] into result.
    while i < arr.len()
        invariant i <= arr.len()
        invariant result.len() == i
        invariant forall |j: usize| j < i ==> result[j] == arr[j]
        decreases arr.len() - i
    {
        // push is total and preserves the invariants
        result.push(arr[i]);
        i = i + 1;
    }
    result
}

} // end verus!  

